	private void ApplyPlayerHealthChange(int delta, bool isHeal = false)
	{
		m_DataJoeyPlayer.lastPlayerHealth = m_DataJoeyPlayer.playerHealth;
		m_DataJoeyPlayer.playerHealth += delta;
		if (m_DataJoeyPlayer.playerHealth < 0)
		{
			m_DataJoeyPlayer.playerHealth = 0;
		}
		if (isHeal && m_DataJoeyPlayer.playerHealth > m_DataJoeyPlayer.playerMaxHealth)
		{
			m_DataJoeyPlayer.playerHealth = m_DataJoeyPlayer.playerMaxHealth;
		}
		if (delta != 0)
		{
			int actualChange = isHeal ? (m_DataJoeyPlayer.playerHealth - m_DataJoeyPlayer.lastPlayerHealth) : Mathf.Abs(delta);
			{
				ShowDamageText(actualChange, m_View.Joey, new Vector3(100f, 190f, 0), !isHeal);
			}
			if (isHeal)
			{
				JoeyGameControl.Instance.PlayVFX(EVFXName.VFX_HuiXue, transform, 2f);
				m_View.JoeyAnim.Play("happy");
			}
			else
			{
				JoeyGameControl.Instance.PlayVFX(EVFXName.VFX_joey_souji, transform, DataSystem.Instance.GetVFXDelayTime(EVFXName.VFX_joey_souji));
				m_View.JoeyAnim.Play("fear");
			}
		}
		if (delta < 0 && !isHeal)
		{
			if (m_ShakeScreenCts != null && !m_ShakeScreenCts.IsCancellationRequested)
			{
				m_ShakeScreenCts.Cancel();
				m_ShakeScreenCts.Dispose();
			}
			m_ShakeScreenCts = new CancellationTokenSource();
			ShakeScreen(0.2f, 20f, m_ShakeScreenCts.Token).Forget();
		}
		OnHPChanged(m_DataJoeyPlayer.playerHealth);
		CheckGameOver();
	}

	private void CheckGameOver()
	{
		if (m_DataJoeyPlayer.playerHealth <= 0)
		{
			DataAchievement achievement = DataSystem.Instance.GetDataAchievement();
			achievement.DeadNum++;
			DataSystem.Instance.SaveDataAchievement();
			JoeyGameControl.Instance.ShowGameOver();
		}
	}

