	private void CreateFistCardCache()
	{
		// Only skip creation if fist card exists and is active, unless it needs to be replaced
		if (m_FistCardCache != null && m_FistCardCache.gameObject.activeSelf)
		{
			// Check if we need to replace the current fist card
			bool hasHighArtRelic = DataSystem.Instance.HasRelic(ERelicType.HighArt);
			bool hasGlovesRelic = DataSystem.Instance.HasRelic(ERelicType.BareHandsMaster);
			bool isBareHands = m_FistCardCache.CardData != null && m_FistCardCache.CardData.id == "1011";
			bool isMagicWand = m_FistCardCache.CardData != null && m_FistCardCache.CardData.id == "1022";

			// 判断是否需要替换当前的拳头卡:
			// 1. 有 HighArt 遗物但当前不是魔杖 → 需要替换为魔杖
			// 2. 有 BareHandsMaster 遗物但当前还是赤手空拳 → 需要替换为拳套
			bool needReplace = (hasHighArtRelic && !isMagicWand) || (hasGlovesRelic && isBareHands);

			if (!needReplace)
			{
				return;
			}

			// 需要替换时，先回收旧的卡片
			m_FistCardCache.Return();
			m_FistCardCache = null;
		}

		// Determine which card to use:
		// HighArt relic takes priority - use Magic Wand (1022)
		// BareHandsMaster relic - use Boxing Gloves (1019)
		// Default - use Bare Hands (1011)
		string cardId;
		if (DataSystem.Instance.HasRelic(ERelicType.HighArt))
		{
			cardId = "1022"; // Magic Wand
		}
		else if (DataSystem.Instance.HasRelic(ERelicType.BareHandsMaster))
		{
			cardId = "1019"; // Boxing Gloves
		}
		else
		{
			cardId = "1011"; // Bare Hands
		}

		Card card = DataSystem.Instance.CreateCard(cardId);
		Transform attackPanelTransform = m_View.AttackPanel.transform;
		UICardSimpleControl cardControl = m_CardSimplePool.Get();
		cardControl.CacheTrans.SetParent(m_View.EmptyAttack);
		cardControl.CacheTrans.position = attackPanelTransform.position;
		cardControl.CacheTrans.localScale = Vector3.one * .8f;
		cardControl.CacheTrans.localEulerAngles = Vector3.zero;
		cardControl.IsEnv = false;
		cardControl.SetData(card);
		m_FistCardCache = cardControl;
	}

	private void CreateKeyPathCardCache()
	{
		if (m_KeyPathCardCache != null)
		{
			return;
		}
		Card card = CreateCard(EXIT_CARD_ID);
		Transform effectRoot2 = GetEffectRoot(2);
		UICardSimpleControl cardControl = Asset.OpenUI<UICardSimpleControl>(effectRoot2);
		cardControl.CacheTrans.localPosition = Vector3.zero;
		cardControl.CacheTrans.localScale = Vector3.one;
		cardControl.CacheTrans.localEulerAngles = Vector3.zero;
		cardControl.IsEnv = true;
		cardControl.SetData(card, isEnv: true, envIndex: 2);
		cardControl.gameObject.SetActive(false);
		m_KeyPathCardCache = cardControl;
	}

	public void ClearEnvCardList()
	{
		for (int i = 0; i < m_EnvPanels.Count; i++)
		{
			if (m_EnvCardDict.TryGetValue(i, out List<UICardSimpleControl> envCardList))
			{
				for (int j = 0; j < envCardList.Count; j++)
				{
					UICardSimpleControl cardControl = envCardList[j];
					if (cardControl != null && cardControl.gameObject.activeSelf)
					{
						m_CardDict.Remove(cardControl.CardData.UniqueId);
						RemoveCardCts(cardControl);
						cardControl.Return();
					}
				}
			}
		}
		m_EnvCardDict.Clear();
	}

	public void ClearBagCardList()
	{
		foreach (var kvp in m_BagCardDict)
		{
			List<UICardSimpleControl> bagCardList = kvp.Value;
			if (bagCardList != null)
			{
				for (int i = 0; i < bagCardList.Count; i++)
				{
					UICardSimpleControl cardControl = bagCardList[i];
					if (cardControl != null && cardControl.gameObject.activeSelf)
					{
						m_CardDict.Remove(cardControl.CardData.UniqueId);
						RemoveCardCts(cardControl);
						cardControl.Return();
					}
				}
			}
		}
		m_BagCardDict.Clear();
	}

