	private void AddCardsFromEquipList(List<int> equipList)
	{
		for (int i = 0; i < equipList.Count; i++)
		{
			int uniqueId = equipList[i];
			Card card = m_DataJoeyPlayer.GetSelfCardDictData(uniqueId);
			if (card == null) continue;

			// HighArt relic takes priority: Replace Bare Hands or Boxing Gloves with Magic Wand
			if (DataSystem.Instance.HasRelic(ERelicType.HighArt) && (card.id == "1011" || card.id == "1019"))
			{
				// Get the magic wand card template
				Card magicWandTemplate = GData.Instance.GetCardConfigById("1022");
				// Replace card data while keeping the unique ID
				card.cardImage = magicWandTemplate.cardImage;
				card.cardBackground = magicWandTemplate.cardBackground;
				card.cardName = magicWandTemplate.cardName;
				card.description = magicWandTemplate.description;
				card.id = magicWandTemplate.id;
				card.SetAttack(magicWandTemplate.currentAttack);
				card.effectId = magicWandTemplate.effectId;
			}
			// Replace Bare Hands with Boxing Gloves if player has BareHandsMaster relic (and not HighArt)
			else if (DataSystem.Instance.HasRelic(ERelicType.BareHandsMaster) && card.id == "1011")
			{
				// Get the boxing gloves card template
				Card boxingGlovesTemplate = GData.Instance.GetCardConfigById("1019");
				// Replace card data while keeping the unique ID
				card.cardImage = boxingGlovesTemplate.cardImage;
				card.cardBackground = boxingGlovesTemplate.cardBackground;
				card.cardName = boxingGlovesTemplate.cardName;
				card.description = boxingGlovesTemplate.description;
				card.id = boxingGlovesTemplate.id;
				card.SetAttack(boxingGlovesTemplate.currentAttack);
				card.effectId = boxingGlovesTemplate.effectId;
			}

			ECardType cardType = card.GetCardType();
			Transform parent = GetParentByCardType(cardType);
			if (parent == null)
			{
				continue;
			}
			m_CardDict[card.UniqueId] = card;
			UICardSimpleControl cardControl = GetCardSimple(parent, false);
			cardControl.SetData(card);
			AddBagCard(cardType, cardControl);
			cardControl.PlayVFX(new List<EVFXName>(), ECardAnimName.UI_Carditem_pailai, EVFXLife.CardLife);
		}
	}

	private void AddBagCard(ECardType cardType, UICardSimpleControl cardControl, bool isMoveCard = false)
	{
		int cardTypeInt = (int)cardType;
		if (!m_BagCardDict.TryGetValue(cardTypeInt, out List<UICardSimpleControl> cardList))
		{
			m_BagCardDict[cardTypeInt] = new List<UICardSimpleControl>();
		}

		// Check if card will become top of pile (last in list)
		bool willBecomeTop = (m_BagCardDict[cardTypeInt].Count == 0);

		m_BagCardDict[cardTypeInt].Add(cardControl);
		cardControl.IsEnv = false;
		cardControl.EnvIndex = -1;
		if (!isMoveCard)
		{
			cardControl.CacheTrans.localScale = new Vector3(0.8f, 0.8f, 0.8f);
		}

	if (cardType == ECardType.defence)
	{
		// Apply Fortress bonus if available
		ApplyFortressBonus(cardControl);

		RunActionForEachLastBagCard((x) =>
		{
			if (x.GetBuffValue(EBuffType.UpdateByDefenceCardNum) > 0)
			{
				x.UpdateBuffValue();
			}

		});
		
		// DualWieldMastery relic: Refresh attack cards when defence is equipped
		if (DataSystem.Instance.HasRelic(ERelicType.DualWieldMastery))
		{
			RefreshAllAttackCards();
		}
	}

		// 螺旋手里剑：当任意攻击卡进入手牌时，检查并移动螺旋手里剑到环境
		// 注意：即使是从环境拿回来的卡（isMoveCard=true），也应该触发此逻辑
		if (cardType == ECardType.attack)
		{
			CheckAndMoveSpiralShurikenToEnv(cardControl);
		}

		// Trigger OnEnterBag if not from move animation (which calls it separately)
		if (!isMoveCard && cardControl.CardEffect != null)
		{
			Debug.Log($"[AddBagCard] Calling OnEnterBag for {cardControl.CardData.cardName} (UniqueId: {cardControl.CardData.UniqueId}, Type: {cardType})");
			cardControl.CardEffect.OnEnterBag();
		}

		// Trigger OnBecomeTopOfPile if card becomes top of pile
		// Skip if isMoveCard=true, as MoveCard callback will handle it
		if (!isMoveCard && willBecomeTop && cardControl.CardEffect != null)
		{
			Debug.Log($"[AddBagCard] Card becomes top of pile, calling OnBecomeTopOfPile for {cardControl.CardData.cardName} (UniqueId: {cardControl.CardData.UniqueId}, Type: {cardType})");
			cardControl.CardEffect.OnBecomeTopOfPile();
		}
	}


	private async UniTask RemoveBagCard(ECardType cardType, UICardSimpleControl cardControl)
	{
		int cardTypeInt = (int)cardType;
		if (m_BagCardDict.TryGetValue(cardTypeInt, out List<UICardSimpleControl> cardList))
		{
			Debug.Log($"[RemoveBagCard] Removing {cardControl.CardData.cardName} (UniqueId: {cardControl.CardData.UniqueId}, Type: {cardType})");
			cardList.Remove(cardControl);
			RemoveCardData(cardControl.CardData.UniqueId);
			cardControl.Return();

			UICardSimpleControl newLastBagCard = GetLastBagCard(cardType);
			if (newLastBagCard != null)
			{
				Debug.Log($"[RemoveBagCard] New top card: {newLastBagCard.CardData.cardName} (UniqueId: {newLastBagCard.CardData.UniqueId}), calling OnBecomeTopOfPile");
				float delayTime = newLastBagCard.CardEffect?.OnBecomeTopOfPile() ?? 0.5f;
				await UniTask.WaitForSeconds(delayTime);
			}
			else
			{
				Debug.Log($"[RemoveBagCard] No cards left in {cardType} pile");
			}
			
			// DualWieldMastery relic: Refresh attack cards when defence is removed
			if (cardType == ECardType.defence && DataSystem.Instance.HasRelic(ERelicType.DualWieldMastery))
			{
				RefreshAllAttackCards();
			}
		}
	}

