	private async UniTask<bool> DealDamageToEnvCard(UICardSimpleControl cardControl, int damage, int envIndex, EEffectType effectType = EEffectType.Damage, CancellationToken? cancellationToken = null)
	{
		CancellationToken token = cancellationToken ?? CancellationToken.None;

		// 应用技能伤害加成
		damage = ApplySkillDamageBonus(damage, effectType);

		if (cardControl.CardType == ECardType.monster)
		{
			// Apply vulnerable damage bonus (50% extra damage)
			int vulnerableTurns = cardControl.GetBuffValue(EBuffType.Vulnerable);
			if (vulnerableTurns > 0 && effectType == EEffectType.Damage)
			{
				int bonusDamage = Mathf.RoundToInt(damage * 0.5f);
				damage += bonusDamage;
				Debug.Log($"Vulnerable: {cardControl.CardData.cardName} takes +{bonusDamage} damage ({vulnerableTurns} turns remaining)");
			}

			float delayTime = cardControl.CallCardTakeDamage(damage, effectType);
			ShowDamageText(damage, cardControl.CacheTrans, new Vector3(0f, 180f, 0));
			{
				if (m_ShakeScreenCts != null && !m_ShakeScreenCts.IsCancellationRequested)
				{
					m_ShakeScreenCts.Cancel();
					m_ShakeScreenCts.Dispose();
				}
				m_ShakeScreenCts = new CancellationTokenSource();
				ShakeScreen(0.2f, 20f, m_ShakeScreenCts.Token).Forget();
			}
			if (delayTime > 0f)
			{
				await UniTask.WaitForSeconds(delayTime, cancellationToken: token);
			}

			// 火球攻击解除冰冻状态
			if (effectType == EEffectType.FireBall && cardControl.IsFrozen())
			{
				cardControl.RemoveBuff(EBuffType.Frozen);
				Debug.Log($"Monster at envIndex {envIndex} unfrozen by FireBall");
			}
		}



		if (cardControl.CardData.currentHealth <= 0 && cardControl.CardType == ECardType.monster)
		{
			Debug.Log("Monster dead: " + cardControl.CardData.id);
			string monsterId = cardControl.CardData.id;
			List<Card> dropCards = GetMonsterDropCard(monsterId, envIndex);

			float delayTime = cardControl.CardEffect?.OnBeDying() ?? 0f;
			await UniTask.WaitForSeconds(delayTime, cancellationToken: token);

			Card configCard = GData.Instance.GetCardConfigById(monsterId);
			if (configCard != null && configCard.stars == 3)
			{
				DataSystem.Instance.AddGrowthPoints(10);
			}

			DataAchievement achievement = DataSystem.Instance.GetDataAchievement();
			if (configCard != null && configCard.price > 0)
			{
				DataSystem.Instance.AddCoin(configCard.price);
				if (m_DataJoeyPlayer.Coin > achievement.MaxCoinNum)
				{
					achievement.MaxCoinNum = m_DataJoeyPlayer.Coin;
				}
			}
			achievement.KillMonsterNum++;
			DataSystem.Instance.SaveDataAchievement();
			// 播放怪物离场音效
			SFX.PlayAudio("Audio/SFX/Battle/MonsterFly", 1.0f, 0.5f);


			RemoveEnvCard(envIndex, cardControl);
			delayTime = cardControl.CardEffect?.OnDead() ?? 0.5f;
			await UniTask.WaitForSeconds(delayTime, cancellationToken: token);
			RemoveCardCts(cardControl);

			if (dropCards != null && dropCards.Count > 0)
			{
				AddEnvDropCard(dropCards, envIndex);
			}

			CheckAndSpawnKeyPath();

			return true;
		}

		return false;
	}

	private List<Card> GetMonsterDropCard(string monsterId, int envIndex)
	{
		if (string.IsNullOrEmpty(monsterId))
		{
			return null;
		}

		// Get current level random seed for deterministic drop
		int levelRandomSeed = DataSystem.Instance.GetDataJoeyPlayer().levelRandomSeed;

		// Use deterministic drop with seed based on random seed and position
		if (!LootDropManager.Instance.TryGetDropCardsWithSeed(monsterId, levelRandomSeed, envIndex, out List<string> cardIds) || cardIds == null || cardIds.Count == 0)
		{
			return null;
		}

		List<Card> dropCards = new List<Card>();
		for (int i = 0; i < cardIds.Count; i++)
		{
			Card card = CreateCard(cardIds[i]);
			dropCards.Add(card);
		}

		return dropCards;
	}

	private void AddEnvDropCard(List<Card> dropCards, int centerIndex)
	{
		if (dropCards == null || dropCards.Count == 0)
		{
			return;
		}

		if (m_EnvPanels == null || m_EnvPanels.Count == 0)
		{
			return;
		}

		centerIndex = Mathf.Clamp(centerIndex, 0, m_EnvPanels.Count - 1);

		var usedIndices = new HashSet<int>();
		var offsetPattern = BuildOffsetPattern(m_EnvPanels.Count);

		for (int i = 0; i < dropCards.Count; i++)
		{
			int panelIndex = FindPanelIndex(centerIndex, usedIndices, offsetPattern, m_EnvPanels.Count);
			if (panelIndex < 0)
			{
				panelIndex = centerIndex;
			}

			panelIndex = Mathf.Clamp(panelIndex, 0, m_EnvPanels.Count - 1);
			VerticalLayoutGroup parent = m_EnvPanels[panelIndex];
			UICardSimpleControl cardControl = GetCardSimple(parent.transform, true);
			cardControl.SetData(dropCards[i], isEnv: true, envIndex: panelIndex);
			AddEnvCard(panelIndex, cardControl);
			cardControl.PlayVFX(new List<EVFXName>(), ECardAnimName.UI_Carditem_pailai, EVFXLife.CardLife);

			usedIndices.Add(panelIndex);
		}
	}

	private List<int> BuildOffsetPattern(int panelCount)
	{
		var offsets = new List<int>();
		offsets.Add(0);
		int step = 1;
		while (offsets.Count < panelCount * 2)
		{
			offsets.Add(-step);
			offsets.Add(step);
			step++;
		}
		return offsets;
	}

	private int FindPanelIndex(int centerIndex, HashSet<int> usedIndices, List<int> offsetPattern, int panelCount)
	{
		for (int i = 0; i < offsetPattern.Count; i++)
		{
			int candidate = centerIndex + offsetPattern[i];
			if (candidate < 0 || candidate >= panelCount) continue;
			if (usedIndices.Contains(candidate)) continue;
			return candidate;
		}

		return Mathf.Clamp(centerIndex, 0, panelCount - 1);
	}

	void BoomEnvCard(object[] paraArray)
