	void RemoveCardData(int uniqueId)
	{
		if (m_CardDict.TryGetValue(uniqueId, out Card card))
		{
			UsedCardList.Add(card);
			m_CardDict.Remove(uniqueId);
		}
	}

	public void ClearAllCard()
	{
		m_CardSimplePool.ForEach(cardControl =>
		{
			if (cardControl != null && cardControl.gameObject.activeSelf && cardControl != m_FistCardCache)
			{
				cardControl.Return();
			}
		});

		m_CardDict.Clear();
		m_EnvCardDict.Clear();
		m_BagCardDict.Clear();
		UsedCardList.Clear();
		ClearAllCardCts();
	}

	private CancellationToken GetOrCreateCardToken(UICardSimpleControl cardControl)
	{
		if (cardControl == null)
		{
			return CancellationToken.None;
		}

		if (!m_CardCtsDict.TryGetValue(cardControl, out CancellationTokenSource cts) || cts == null || cts.IsCancellationRequested)
		{
			if (cts != null)
			{
				cts.Dispose();
				m_CardCtsDict.Remove(cardControl);
			}
			cts = new CancellationTokenSource();
			m_CardCtsDict[cardControl] = cts;
			string cardId = cardControl?.CardData?.id ?? "null";
			string cardName = cardControl?.CardData?.cardName ?? "null";
			Debug.Log($"[AddCardCts] CardId: {cardId}, CardName: {cardName}, DictCount: {m_CardCtsDict.Count}");
		}

		return cts.Token;
	}

	private void RemoveCardCts(UICardSimpleControl cardControl)
	{
		if (cardControl == null)
		{
			return;
		}



		if (!m_CardCtsDict.TryGetValue(cardControl, out CancellationTokenSource cts))
		{
			string cardId = cardControl?.CardData?.id ?? "null";
			string cardName = cardControl?.CardData?.cardName ?? "null";
			Debug.LogWarning($"[RemoveCardCts] CardId: {cardId}, CardName: {cardName} not found in dict, DictCount: {m_CardCtsDict.Count}");
			return;
		}

		if (cts != null)
		{
			cts.Cancel();
			cts.Dispose();
		}
		m_CardCtsDict.Remove(cardControl);
		string cardId2 = cardControl?.CardData?.id ?? "null";
		string cardName2 = cardControl?.CardData?.cardName ?? "null";
		Debug.Log($"[RemoveCardCts] CardId: {cardId2}, CardName: {cardName2}, DictCount: {m_CardCtsDict.Count}");
	}

	private void ClearAllCardCts()
	{
		foreach (var kvp in m_CardCtsDict)
		{
			if (kvp.Value != null)
			{
				kvp.Value.Cancel();
				kvp.Value.Dispose();
			}
		}
		m_CardCtsDict.Clear();
	}

	public void ClearAllUniTasks()
	{
		ClearAllCardCts();
		m_MoveCardDelayAction.Cancel();
		if (m_ShakeScreenCts != null && !m_ShakeScreenCts.IsCancellationRequested)
		{
			m_ShakeScreenCts.Cancel();
			m_ShakeScreenCts.Dispose();
		}
		m_ShakeScreenCts = null;
		if (m_MoveBagCardsCts != null && !m_MoveBagCardsCts.IsCancellationRequested)
		{
			m_MoveBagCardsCts.Cancel();
			m_MoveBagCardsCts.Dispose();
		}
		m_MoveBagCardsCts = null;
	}

	async void MoveCard(object[] paraArray)
	{
		bool isEnv = (bool)paraArray[0];
		UICardSimpleControl cardControl = (UICardSimpleControl)paraArray[1];
		cardControl.SetMoving(true);
		if (isEnv)
		{
			// 播放拿牌音效
			SFX.PlayAudio("Audio/SFX/deal_cards", 1.9f, 0.5f);

			// 魔剑士指环效果：加入手牌时转换武器牌/防御牌
			TryApplyMagicSwordsmanRing(cardControl);

			ECardType cardType = cardControl.CardType;

			Vector3 startWorldPos = cardControl.CacheTrans.parent.position;
			Vector3 startScale = Vector3.one;

			RemoveEnvCardFromDict(cardControl.EnvIndex, cardControl);
			AddBagCard(cardType, cardControl, true);

			VerticalLayoutGroup layout = null;
			switch (cardType)
			{
				case ECardType.attack:
					layout = m_View.AttackPanel;
					break;
				case ECardType.defence:
					layout = m_View.DefencePanel;
					break;
				case ECardType.skill:
					layout = m_View.SkillPanel;
					break;
				case ECardType.item:
					layout = m_View.ItemPanel;
					break;
				default:
					return;
			}

			Vector3 endScale = new Vector3(0.8f, 0.8f, 1.0f);
			float duration = .2f;
			Vector3 endPos = layout.transform.position;

			m_MoveCardDelayAction.AddAnimDelayAction(
				(cancellationToken) => MoveCardAnimation(cardControl, startWorldPos, endPos, startScale, endScale, duration, layout, cancellationToken),
				() =>
				{
					cardControl.CacheTrans.position = endPos;
					cardControl.CacheTrans.localScale = endScale;
					cardControl.CacheTrans.localEulerAngles = Vector3.zero;
					layout.enabled = true;
					cardControl.SetMoving(false);
					
					// Trigger OnEnterBag for the moved card
					if (cardControl.CardEffect != null)
					{
						Debug.Log($"[MoveCard] Calling OnEnterBag for moved card: {cardControl.CardData.cardName} (UniqueId: {cardControl.CardData.UniqueId}, Type: {cardType})");
						cardControl.CardEffect.OnEnterBag();
					}
					
					// Check if the moved card becomes top of pile
					UICardSimpleControl lastBagCard = GetLastBagCard(cardType);
					if (lastBagCard == cardControl && cardControl.CardEffect != null)
					{
						Debug.Log($"[MoveCard] Moved card becomes top of pile, calling OnBecomeTopOfPile for {cardControl.CardData.cardName} (UniqueId: {cardControl.CardData.UniqueId}, Type: {cardType})");
						cardControl.CardEffect.OnBecomeTopOfPile();
					}
					
					// Also trigger OnEnterBag for CurrentEffectCard (the item/skill that caused the move)
					if (CurrentEffectCard != null)
					{
						CurrentEffectCard.CardEffect?.OnEnterBag();

						CurrentEffectCard.IsEffecting = false;
						RemoveCardCts(CurrentEffectCard);
					}

				}
			);
		}
	}

	private async UniTask MoveCardAnimation(UICardSimpleControl cardControl, Vector3 startPos, Vector3 endPos, Vector3 startScale, Vector3 endScale, float duration, VerticalLayoutGroup layout, CancellationToken cancellationToken)
	{
		if (layout != null)
		{
			layout.enabled = false;
			cardControl.CacheTrans.SetParent(layout.transform);
		}

		float elapsed = 0f;
		while (elapsed < duration)
		{
			cancellationToken.ThrowIfCancellationRequested();
			elapsed += Time.deltaTime;
			float t = elapsed / duration;

			cardControl.CacheTrans.position = Vector3.Lerp(startPos, endPos, t);
			cardControl.CacheTrans.localScale = Vector3.Lerp(startScale, endScale, t);

			//Debug.Log($"MoveCard Animation - Position: {cardControl.CacheTrans.position}, Scale: {cardControl.CacheTrans.localScale}, t: {t}");

			await UniTask.Yield(cancellationToken);
		}
	}

	public void MoveBagCardsToCoinAndShowReward()
	{
		if (m_MoveBagCardsCts != null && !m_MoveBagCardsCts.IsCancellationRequested)
		{
			m_MoveBagCardsCts.Cancel();
			m_MoveBagCardsCts.Dispose();
		}
		m_MoveBagCardsCts = new CancellationTokenSource();
		MoveBagCardsToCoinAndShowRewardAsync(m_MoveBagCardsCts.Token).Forget();
	}

	private async UniTaskVoid MoveBagCardsToCoinAndShowRewardAsync(CancellationToken cancellationToken)
	{
		List<UICardSimpleControl> bagCards = new List<UICardSimpleControl>();
		foreach (var kvp in m_BagCardDict)
		{
			List<UICardSimpleControl> cardList = kvp.Value;
			for (int i = 0; i < cardList.Count; i++)
			{
				UICardSimpleControl cardControl = cardList[i];
				if (cardControl != m_FistCardCache)
				{
					bagCards.Add(cardControl);
				}
			}
		}

		Vector3 targetPos = m_View.TxtCoin.transform.position;
		float duration = 0.5f;

		List<UniTask> animationTasks = new List<UniTask>();
		for (int i = 0; i < bagCards.Count; i++)
		{
			UICardSimpleControl cardControl = bagCards[i];
			cardControl.transform.SetParent(Asset.UIRoot);
			Vector3 startPos = cardControl.CacheTrans.position;
			Vector3 startScale = cardControl.CacheTrans.localScale;
			Vector3 endScale = Vector3.zero;

			animationTasks.Add(MoveCardAnimation(cardControl, startPos, targetPos, startScale, endScale, duration, null, CancellationToken.None));
		}

		await UniTask.WhenAll(animationTasks);

		for (int i = 0; i < bagCards.Count; i++)
		{
			UICardSimpleControl cardControl = bagCards[i];
			RemoveCardData(cardControl.CardData.UniqueId);
			RemoveCardCts(cardControl);
			cardControl.Return();
		}


		int coinReward = bagCards.Count * 5;
		if (coinReward > 0)
		{
			DataSystem.Instance.AddCoin(coinReward);
			OnCoinChanged(m_DataJoeyPlayer.Coin);
			DataAchievement achievement = DataSystem.Instance.GetDataAchievement();
			if (m_DataJoeyPlayer.Coin > achievement.MaxCoinNum)
			{
				achievement.MaxCoinNum = m_DataJoeyPlayer.Coin;
				DataSystem.Instance.SaveDataAchievement();
			}
			UIDamageTextControl damageTextControl = m_DamageTextPool.Get();
			damageTextControl.SetCoinData(coinReward, Asset.UIRoot, Vector3.zero);
			damageTextControl.transform.position = m_View.TxtCoin.transform.position - new Vector3(1f, 1f, 0f);
		}
	}

	async void TakeEnemyDamage(object[] paraArray)
	{
		UICardSimpleControl enemyCardControl = (UICardSimpleControl)paraArray[0];
		int attackCount = (int)paraArray[1];
		int envIndex = (int)paraArray[2];
		m_CurrentAttackTargetEnvIndex = envIndex;  // 记录当前攻击目标位置，供溅射效果使用
		UICardSimpleControl attackCardControl = GetLastBagCard(ECardType.attack);
		if (attackCardControl == null)
		{
			attackCardControl = GetFistCard();
		}
		bool useFistCard = attackCardControl == m_FistCardCache;


		attackCount += attackCardControl.CardEffect?.GetEffectValue(EEffectType.ExtraAttackCnt) ?? 0;

		// DoublePunch relic: bare hands can attack twice
		if (DataSystem.Instance.HasRelic(ERelicType.DoublePunch))
		{
			if (attackCardControl.CardEffect != null && attackCardControl.CardEffect.Id == ECardEffectId.BareHands)
			{
				attackCount += 1;
			}
		}

		Card attackCard = attackCardControl.CardData;
		int damage = attackCard.currentAttack;
		float delayTime;
		delayTime = attackCardControl.CardEffect?.UseAttack() ?? 0f;
		await UniTask.WaitForSeconds(delayTime, cancellationToken: GetOrCreateCardToken(attackCardControl));

		if (useFistCard)
		{
			DataAchievement achievement = DataSystem.Instance.GetDataAchievement();
			achievement.FistUseNum++;
			DataSystem.Instance.SaveDataAchievement();
		}



		if (DataSystem.Instance.HasRelic(ERelicType.GetSpecialCardByAttack))
		{
			if (ControlUtil.IsRandomSucceed(5))
			{
				AddCardToBag("3009");
			}
		}

	bool hasSlowAttack = attackCardControl.CardEffect?.GetEffectValue(EEffectType.SlowAttack) > 0;
	bool enemyCounteredFirst = false;
	if (hasSlowAttack && enemyCardControl != null && enemyCardControl.gameObject.activeSelf && enemyCardControl.CardData.currentHealth > 0)
	{
		int enemyAttack = enemyCardControl.CardData.currentAttack;
		if (enemyAttack > 0)
		{
			CancellationToken enemyToken = GetOrCreateCardToken(enemyCardControl);
			await TakePlayerDamageAsync(enemyAttack, enemyCardControl, envIndex, enemyToken, attackCardControl);
			enemyCounteredFirst = true;
		}
	}

	// Cache NoCounterAttack flag before dealing damage, because enemy's OnTakeDamage may remove the weapon (e.g. BigDumbDonkey kicks weapon away)
	bool hasNoCounterAttack = attackCardControl.CardEffect?.GetEffectValue(EEffectType.NoCounterAttack) > 0;

	bool enemyKilled = false;
		for (int i = 0; i < attackCount; i++)
		{
			// Reset damage to base attack for each attack iteration
			damage = attackCard.currentAttack;
			
			if (DataSystem.Instance.HasRelic(ERelicType.LifeSteal))
			{
				YActionSystem.Instance.DispatchAction(EActionId.AddHp, 1);
			}
			delayTime = attackCardControl.CardEffect?.OnDealDamage() ?? 0.5f;

			damage += attackCardControl.CardEffect.GetEffectValue(EEffectType.Damage);
			// 染血拳套relic效果：血量低于50%时，赤手空拳/拳套的伤害+5
			if (DataSystem.Instance.HasRelic(ERelicType.BloodyGloves))
			{
				if (attackCardControl.CardEffect != null && attackCardControl.CardEffect.Id == ECardEffectId.BareHands)
				{
					if (JoeyGameControl.Instance.IsPlayerHalfHealth())
					{
						damage += 5;
					}
				}
			}
			// 双持精通relic效果：没有装备防具时，所有伤害+5
			if (DataSystem.Instance.HasRelic(ERelicType.DualWieldMastery))
			{
				if (!HasBagCard(ECardType.defence))
				{
					damage += 5;
				}
			}
			await UniTask.WaitForSeconds(delayTime, cancellationToken: GetOrCreateCardToken(attackCardControl));

			bool isKilled = await DealDamageToEnvCard(enemyCardControl, damage, envIndex, EEffectType.Damage, GetOrCreateCardToken(attackCardControl));

			// Apply Strike vulnerable effect after damage is dealt (but before checking if killed)
			if (!isKilled)
			{
				ApplyStrikeVulnerable(enemyCardControl);
			}

			if (damage > 0)
			{
				DataAchievement achievement = DataSystem.Instance.GetDataAchievement();
				if (damage > achievement.MaxDamageNum)
				{
					achievement.MaxDamageNum = damage;
					DataSystem.Instance.SaveDataAchievement();
				}
			}
			if (isKilled)
			{
				enemyKilled = true;

				delayTime = attackCardControl.CardEffect?.OnKill() ?? 0.5f;
				await UniTask.WaitForSeconds(delayTime, cancellationToken: GetOrCreateCardToken(attackCardControl));

				if (DataSystem.Instance.HasRelic(ERelicType.HealOnKill))
				{
					AddHp(3);
				}

			break;
		}
	}

	// 检查怪物是否被冰冻
		bool isEnemyFrozen = enemyCardControl != null && enemyCardControl.IsFrozen();
		if (isEnemyFrozen)
		{
			// 被冰冻的怪物受到武器攻击后解冻，不进行反击
			enemyCardControl.RemoveBuff(EBuffType.Frozen);
			Debug.Log($"Monster at envIndex {envIndex} unfrozen after weapon attack");
		}

		if (!enemyKilled && !hasNoCounterAttack && !enemyCounteredFirst && !isEnemyFrozen && enemyCardControl != null && enemyCardControl.gameObject.activeSelf && enemyCardControl.CardData.currentHealth > 0)
		{
			int enemyAttack = enemyCardControl.CardData.currentAttack;
			CancellationToken enemyToken = GetOrCreateCardToken(enemyCardControl);
			await TakePlayerDamageAsync(enemyAttack, enemyCardControl, envIndex, enemyToken, attackCardControl);
		}

		// Play card consumption animation after enemy counter-attack (if any)
		// This ensures counter-insight parry/counter animations complete before the card disappears
		bool isSkip = IsUseAttackFinishAnim();
		float finishDelayTime = attackCardControl.CardEffect?.OnUseFinished(isSkip) ?? 0f;
		if (finishDelayTime > 0f)
		{
			await UniTask.WaitForSeconds(finishDelayTime, cancellationToken: GetOrCreateCardToken(attackCardControl));
		}


		if (!useFistCard)
		{
			// Check if card should be kept in bag (durability mechanic)
			bool shouldKeep = attackCardControl.CardEffect?.ShouldKeepInBag() ?? false;

			if (!shouldKeep)
			{
				await RemoveBagCard(ECardType.attack, attackCardControl);
				float removeDelayTime = attackCardControl.CardEffect?.OnRemoveCard() ?? 0f;
				if (removeDelayTime > 0f)
				{
					await UniTask.WaitForSeconds(removeDelayTime, cancellationToken: GetOrCreateCardToken(attackCardControl));
				}

				// Check if attack bag is empty, if so trigger fist card's OnBecomeTopOfPile
				UICardSimpleControl nextAttackCard = GetLastBagCard(ECardType.attack);
				if (nextAttackCard == null && m_FistCardCache != null)
				{
					float fistDelayTime = m_FistCardCache.CardEffect?.OnBecomeTopOfPile() ?? 0f;
					if (fistDelayTime > 0f)
					{
						await UniTask.WaitForSeconds(fistDelayTime);
					}
				}
			}
		}
		else
		{
			m_FistCardCache.ClearEffectVlaue();

		}




		RemoveCardCts(attackCardControl);

		// Consume DualWield buff after attack
		ConsumeDualWieldBuff();
		// Consume ShieldBash buff after attack
		ConsumeShieldBashBuff();

		// Clean up enemy card's CTS if it wasn't already removed during counter-attack
		if (m_CardCtsDict.ContainsKey(enemyCardControl))
		{
			RemoveCardCts(enemyCardControl);
		}

		enemyCardControl.IsEffecting = false;
	}

	async void TakePlayerDamage(object[] paraArray)
	{
		int enemyAttack = (int)paraArray[0];
		UICardSimpleControl enemyCardControl = (UICardSimpleControl)paraArray[1];
		int envIndex = (int)paraArray[2];
		CancellationToken enemyToken = GetOrCreateCardToken(enemyCardControl);
		await TakePlayerDamageAsync(enemyAttack, enemyCardControl, envIndex, enemyToken, null);
	}

	async UniTask TakePlayerDamageAsync(int enemyAttack, UICardSimpleControl enemyCardControl, int envIndex, CancellationToken cancellationToken = default, UICardSimpleControl attackCardControl = null)
	{
		if (!m_CardCtsDict.TryGetValue(enemyCardControl, out CancellationTokenSource _))
		{
			return;
		}

		// Play enemy attack animation first
		currentMonsterAttack = enemyAttack;
		float delayTime = enemyCardControl.CardEffect?.OnDealDamage() ?? 0.5f;
		await UniTask.WaitForSeconds(delayTime, cancellationToken: cancellationToken);

		// Check CounterInsight relic for dodge and counter-attack (after enemy animation)
		bool dodgedWithCounterInsight = await TryCounterInsightDodge(enemyCardControl, enemyAttack, envIndex, cancellationToken);
		if (dodgedWithCounterInsight)
		{
			// Attack was dodged and countered, skip damage processing
			RemoveCardCts(enemyCardControl);
			currentMonsterAttack = 0;
			return;
		}

		// Increment CounterInsight counter (if relic is equipped)
		IncrementCounterInsight();

		int defenceValue = 0;
		UICardSimpleControl defenceCardControl = GetLastBagCard(ECardType.defence);
		bool usedWeaponParry = false;

		// Check if DualWield is active - if so, cannot use defence cards
		if (m_DualWieldActive && defenceCardControl != null)
		{
			Debug.Log("DualWield active: Cannot use defence cards!");
			defenceCardControl = null; // Disable defence card usage
		}

		// If no defence card, check for WeaponParry relic to use weapon as defence
		if (defenceCardControl == null && DataSystem.Instance.HasRelic(ERelicType.WeaponParry))
		{
			UICardSimpleControl weaponCard = GetLastBagCard(ECardType.attack);
			if (weaponCard != null && weaponCard != m_FistCardCache)
			{
				// Calculate current weapon attack including all bonuses
				int currentWeaponAttack = weaponCard.CardData.currentAttack;
				currentWeaponAttack += weaponCard.CardEffect?.GetEffectValue(EEffectType.Damage) ?? 0;
				
				// Add BloodyGloves relic bonus if applicable
				if (DataSystem.Instance.HasRelic(ERelicType.BloodyGloves))
				{
					if (weaponCard.CardEffect != null && weaponCard.CardEffect.Id == ECardEffectId.BareHands)
					{
						if (JoeyGameControl.Instance.IsPlayerHalfHealth())
						{
							currentWeaponAttack += 5;
						}
					}
				}
				
				// Add DualWieldMastery relic bonus if applicable
				if (DataSystem.Instance.HasRelic(ERelicType.DualWieldMastery))
				{
					if (!HasBagCard(ECardType.defence))
					{
						currentWeaponAttack += 5;
					}
				}
				
				// Use weapon as defence (defence value = 20% of current weapon attack)
				defenceCardControl = weaponCard;
				defenceValue = Mathf.RoundToInt(currentWeaponAttack * 0.2f);
				usedWeaponParry = true;

				bool isOverflow = defenceValue < enemyAttack;
				// Play defence animation
				var vfxNames = new List<EVFXName> { EVFXName.VFX_Dun };
				float vfxDelay = defenceCardControl.PlayVFX(vfxNames, ECardAnimName.UI_Carditem_dunpai, EVFXLife.SelfLife);
				SFX.PlayAudio("Audio/SFX/Battle/Defence", 1.0f, 0f);
				delayTime = vfxDelay > 0f ? vfxDelay : 0.5f;
				await UniTask.WaitForSeconds(delayTime, cancellationToken: GetOrCreateCardToken(defenceCardControl));
			}
		}
		else if (defenceCardControl != null)
		{
			defenceValue = defenceCardControl.CardData.currentDefence + (defenceCardControl.CardEffect?.GetEffectValue(EEffectType.Defence) ?? 0);
			bool isOverflow = defenceValue < enemyAttack;
			delayTime = defenceCardControl.CardEffect?.UseDefence(isOverflow) ?? 0.5f;
			await UniTask.WaitForSeconds(delayTime, cancellationToken: GetOrCreateCardToken(defenceCardControl));

			if (DataSystem.Instance.HasRelic(ERelicType.GetSpecialCardByDefence))
			{
				if (ControlUtil.IsRandomSucceed(10))
				{
					AddCardToBag("3010");
				}
			}
		}
		int damage = 0;
		if (defenceValue < enemyAttack)
		{
			damage = enemyAttack - defenceValue;
			if (DataSystem.Instance.HasRelic(ERelicType.Callus) && damage > 0 && damage < 3)
			{
				damage = 0;
			}
		}

		// BareHandParry relic: Block half damage when no weapon and no defence equipped
		if (DataSystem.Instance.HasRelic(ERelicType.BareHandParry) && damage > 0)
		{
			bool hasNoWeapon = !HasBagCard(ECardType.attack);
			bool hasNoDefence = !HasBagCard(ECardType.defence);

			if (hasNoWeapon && hasNoDefence)
			{
				int blockedDamage = damage / 2;
				damage = damage - blockedDamage;
				Debug.Log($"BareHandParry: Blocked {blockedDamage} damage, remaining damage: {damage}");

				// Play defence animation on fist card (bare hands weapon)
				if (m_FistCardCache != null)
				{
					var vfxNames = new List<EVFXName> { EVFXName.VFX_Dun };
					float vfxDelay = m_FistCardCache.PlayVFX(vfxNames, ECardAnimName.UI_Carditem_dunpai, EVFXLife.SelfLife);
					SFX.PlayAudio("Audio/SFX/Battle/Defence", 1.0f, 0f);
					delayTime = vfxDelay > 0f ? vfxDelay : 0.3f;
					await UniTask.WaitForSeconds(delayTime, cancellationToken: GetOrCreateCardToken(m_FistCardCache));
				}
				else
				{
					// Fallback to player visual effect if fist card not available
					JoeyGameControl.Instance.PlayVFX(EVFXName.VFX_Dun, m_View.Joey, 0.3f);
				}
			}
		}

		if (damage > 0 && TryBlockFatalDamage(damage))
		{
			damage = m_DataJoeyPlayer.playerHealth - 1;
		}

		// Only play hit sound if actually taking damage
		if (damage > 0)
		{
			SFX.PlayAudio("Audio/SFX/Battle/MonsterOnAttack", 1.0f, 0f);
		}
		ApplyPlayerHealthChange(-damage);
		OnAttackChanged(m_DataJoeyPlayer.playerAttack);
		OnDefenceChanged(m_DataJoeyPlayer.playerDefence);

		if (damage > 0)
		{
			DataAchievement achievement = DataSystem.Instance.GetDataAchievement();
			if (damage > achievement.MaxTakeDamageNum)
			{
				achievement.MaxTakeDamageNum = damage;
				DataSystem.Instance.SaveDataAchievement();
			}
		}

		if (defenceCardControl != null)
		{
			// Handle weapon parry or normal defence card
			int reflectDamage = defenceCardControl.CardEffect?.GetEffectValue(EEffectType.ReflectDamage) ?? 0;

			if (DataSystem.Instance.HasRelic(ERelicType.ShieldReflect) && !usedWeaponParry)
			{
				int shieldDefence = defenceValue;
				int relicReflectDamage = shieldDefence / 2;
				if (relicReflectDamage > 0)
				{
					reflectDamage += relicReflectDamage;
				}
			}

			if (reflectDamage > 0)
			{
				await AttackSpecialEnemy(enemyCardControl, reflectDamage, envIndex, GetOrCreateCardToken(defenceCardControl));
			}
			
			// Call OnUseFinished for both weapon parry and normal defence cards
			// This handles durability reduction for cards like Knight Sword
			float finishDelayTime = defenceCardControl.CardEffect?.OnUseFinished(false) ?? 0f;
			if (finishDelayTime > 0f)
			{
				await UniTask.WaitForSeconds(finishDelayTime, cancellationToken: GetOrCreateCardToken(defenceCardControl));
			}

			// Check if card should be kept in bag (durability mechanic)
			bool shouldKeep = defenceCardControl.CardEffect?.ShouldKeepInBag() ?? false;

			if (!shouldKeep)
			{
				// Remove from appropriate bag type (attack for weapon parry, defence for normal)
				ECardType cardType = usedWeaponParry ? ECardType.attack : ECardType.defence;
				await RemoveBagCard(cardType, defenceCardControl);
				float removeDelayTime = defenceCardControl.CardEffect?.OnRemoveCard() ?? 0f;
				if (removeDelayTime > 0f)
				{
					await UniTask.WaitForSeconds(removeDelayTime, cancellationToken: GetOrCreateCardToken(defenceCardControl));
				}
			}

			// Always remove card token (cleanup) regardless of whether card is kept
			RemoveCardCts(defenceCardControl);
		}
		if (DataSystem.Instance.HasRelic(ERelicType.ThornBlessing))
		{
			await AttackSpecialEnemy(enemyCardControl, 3, envIndex, cancellationToken);
		}

		RemoveCardCts(enemyCardControl);
		currentMonsterAttack = 0;
	}

