	void UpdateRelic(object[] paraArray)
	{
		RefreshRelicDisplay();
		int relicId = (int)paraArray[0];
		UpdateAllCardsRelic(relicId);
		
		// DualWieldMastery relic: Refresh attack cards to show bonus
		if (relicId == (int)ERelicType.DualWieldMastery)
		{
			RefreshAllAttackCards();
		}
	}

	private void UpdateAllCardsRelic(int relicId)
	{
		foreach (var kvp in m_BagCardDict)
		{
			List<UICardSimpleControl> bagCardList = kvp.Value;
			for (int i = 0; i < bagCardList.Count; i++)
			{
				UICardSimpleControl cardControl = bagCardList[i];
				cardControl.AddRelic(relicId);
			}
		}

		// Special handling for BareHandsMaster or HighArt relic: recreate fist card cache
		if (relicId == (int)ERelicType.BareHandsMaster || relicId == (int)ERelicType.HighArt)
		{
			if (m_FistCardCache != null)
			{
				m_FistCardCache.Return();
				m_FistCardCache = null;
			}
			CreateFistCardCache();
		}
		else
		{
			m_FistCardCache.AddRelic(relicId);
		}

		foreach (var kvp in m_EnvCardDict)
		{
			List<UICardSimpleControl> envCardList = kvp.Value;
			for (int i = 0; i < envCardList.Count; i++)
			{
				UICardSimpleControl cardControl = envCardList[i];
				if (cardControl.CardType != ECardType.monster && cardControl.CardType != ECardType.other)
				{
					cardControl.AddRelic(relicId);
				}
			}
		}
	}
	
	private void RefreshAllAttackCards()
	{
		// Refresh all attack cards in bag
		List<UICardSimpleControl> attackCardList = GetBagCardList(ECardType.attack);
		if (attackCardList != null)
		{
			for (int i = 0; i < attackCardList.Count; i++)
			{
				attackCardList[i].RefreshCard();
			}
		}
		
		// Refresh fist card (bare hands)
		if (m_FistCardCache != null)
		{
			m_FistCardCache.RefreshCard();
		}
	}

	void OnCardPointerEnter(object[] paraArray)
	{
		UICardSimpleControl cardControl = (UICardSimpleControl)paraArray[0];
		if (cardControl == null)
		{
			return;
		}

		bool shouldShow = false;
		if (cardControl.IsEnv)
		{
			UICardSimpleControl lastEnvCard = GetLastEnvCard(cardControl.EnvIndex);
			if (lastEnvCard == cardControl)
			{
				shouldShow = true;
			}
		}
		else
		{
			shouldShow = true;
		}

		if (shouldShow)
		{
			cardControl.ShowCardHoverEffect();
		}
	}

	private void OnBlockFatalPointerEnter(GameObject go, UnityEngine.EventSystems.PointerEventData eventData)
	{
		if (m_BlockDamagePhaseEnd > 0 && PhaseCounter <= m_BlockDamagePhaseEnd)
		{
			int remainingTurns = m_BlockDamagePhaseEnd - PhaseCounter + 1;
			m_BlockFatalDescExtControl = Asset.OpenUI<UIDescExtControl>(Asset.UIRoot);
			m_BlockFatalDescExtControl.SetData("无敌剩余回合数: " + remainingTurns);
			RectTransform blockFatalRect = m_View.BlockFatal.transform as RectTransform;
			m_BlockFatalDescExtControl.SetPositionRelativeTo(blockFatalRect);
		}
	}

	private void OnBlockFatalPointerExit(GameObject go, UnityEngine.EventSystems.PointerEventData eventData)
	{
		if (m_BlockFatalDescExtControl != null)
		{
			m_BlockFatalDescExtControl.Close();
			m_BlockFatalDescExtControl = null;
		}
	}

	private void UpdateBlockFatalDisplay()
	{
		bool shouldShowBlockFatal = m_BlockDamagePhaseEnd > 0 && PhaseCounter <= m_BlockDamagePhaseEnd;

		if (m_IsBlockFatalActive != shouldShowBlockFatal)
		{
			m_View.BlockFatal.SetActive(shouldShowBlockFatal);
			m_IsBlockFatalActive = shouldShowBlockFatal;
		}

		if (shouldShowBlockFatal)
		{
			int remainingTurns = m_BlockDamagePhaseEnd - PhaseCounter;
			m_View.TxtPhaseBlock.text = remainingTurns.ToString();
		}
	}

