	/// <summary>
	/// Check and display card limit debuff in Env mode
	/// </summary>
	private void RefreshCardLimitDebuff()
	{
		// Only apply in Env mode
		if (JoeyGameControl.Instance == null || JoeyGameControl.Instance.GameMode != EGameMode.Env)
		{
			if (m_CardLimitDebuffControl != null)
			{
				m_CardLimitDebuffControl.gameObject.SetActive(false);
			}
			return;
		}

		// Get card limit from character config
		RoguelikeCharacter characterData = GData.Instance.GetRoguelikeCharacter();
		int cardLimit = characterData != null ? characterData.envCardLimit : 0;

		// If no limit set, hide debuff
		if (cardLimit <= 0)
		{
			if (m_CardLimitDebuffControl != null)
			{
				m_CardLimitDebuffControl.gameObject.SetActive(false);
			}
			return;
		}

		// Check if player's card pool exceeds the limit
		int currentCardCount = m_DataJoeyPlayer != null ? m_DataJoeyPlayer.EnvCardPool.Count : 0;
		bool isOverLimit = currentCardCount > cardLimit;

		if (isOverLimit)
		{
			// Create debuff control if not exists
			if (m_CardLimitDebuffControl == null)
			{
				m_CardLimitDebuffControl = Asset.OpenUI<UIRelicControl>(m_View.RelicContent);
				m_CardLimitDebuffControl.CacheTrans.localScale = Vector3.one;
				m_CardLimitDebuffControl.CacheTrans.localPosition = Vector3.zero;
				m_CardLimitDebuffControl.CacheTrans.localEulerAngles = Vector3.zero;
			}

			// Get base debuff info from config and parse template placeholders
			RelicInfo baseInfo = GData.Instance.GetRelicInfo(ERelicType.CardLimitDebuff);
			if (baseInfo != null)
			{
				// Parse template placeholders: {cardLimit}, {currentCount}
				string dynamicDescription = baseInfo.description
					.Replace("{cardLimit}", cardLimit.ToString())
					.Replace("{currentCount}", currentCardCount.ToString());

				// Create a new RelicInfo with parsed description
				RelicInfo dynamicDebuffInfo = new RelicInfo(
					id: baseInfo.id,
					cardImage: baseInfo.cardImage,
					iconImage: baseInfo.iconImage,
					name: baseInfo.name,
					description: dynamicDescription,
					stars: baseInfo.stars
				);

				m_CardLimitDebuffControl.gameObject.SetActive(true);
				m_CardLimitDebuffControl.SetGameData(dynamicDebuffInfo);
				m_CardLimitDebuffControl.ImgRelicTransform.localScale = Vector3.one * 2f;
			}
		}
		else
		{
			// Hide debuff when under limit
			if (m_CardLimitDebuffControl != null)
			{
				m_CardLimitDebuffControl.gameObject.SetActive(false);
			}
		}
	}

	protected override void OnClose()
	{
		for (int i = 0; i < m_RelicList.Count; i++)
		{
			if (m_RelicList[i] != null)
			{
				m_RelicList[i].Close();
			}
		}
		if (m_CardLimitDebuffControl != null)
		{
			m_CardLimitDebuffControl.Close();
		}

		ClearAllUniTasks();
		CurrentEffectCard = null;
		m_CardActionQueue.Clear();

		foreach (var kvp in m_BagCardDict)
		{
			List<UICardSimpleControl> cardList = kvp.Value;
			if (cardList != null)
			{
				for (int i = 0; i < cardList.Count; i++)
				{
					UICardSimpleControl cardControl = cardList[i];
					if (cardControl != null && cardControl != m_FistCardCache)
					{
						cardControl.Close();
					}
				}
			}
		}

		foreach (var kvp in m_EnvCardDict)
		{
			List<UICardSimpleControl> cardList = kvp.Value;
			if (cardList != null)
			{
				for (int i = 0; i < cardList.Count; i++)
				{
					UICardSimpleControl cardControl = cardList[i];
					if (cardControl != null)
					{
						cardControl.Close();
					}
				}
			}
		}

		for (int i = 0; i < m_YGrimReaperList.Count; i++)
		{
			UICardSimpleControl cardControl = m_YGrimReaperList[i];
			if (cardControl != null)
			{
				cardControl.Close();
			}
		}

		if (m_FistCardCache != null)
		{
			m_FistCardCache.Close();
		}
		if (m_KeyPathCardCache != null)
		{
			m_KeyPathCardCache.Close();
		}

		if (m_CardSimplePool != null)
		{
			m_CardSimplePool.DestroyAll();
			m_CardSimplePool = null;
		}

		if (m_DamageTextPool != null)
		{
			m_DamageTextPool.DestroyAll();
			m_DamageTextPool = null;
		}

		m_EnvPanels.Clear();
		m_CardDict.Clear();
		m_RelicList.Clear();
		m_EnvCardDict.Clear();
		m_BagCardDict.Clear();
		UsedCardList.Clear();
		m_YGrimReaperList.Clear();
		m_CardCtsDict.Clear();

		m_View = null;
		m_DataJoeyPlayer = null;
		m_EffectRoots = null;
		m_FistCardCache = null;
		m_KeyPathCardCache = null;

		base.OnClose();
	}

	private void TryRegenerationHeal()
	{
		if (DataSystem.Instance.HasRelic(ERelicType.RegenerationAmulet))
		{
			if (PhaseCounter > 0 && PhaseCounter % 3 == 0)
			{
				ApplyPlayerHealthChange(1, true);
			}
		}
	}

	private void TryHalfHealthAmulet()
	{
		if (DataSystem.Instance.HasRelic(ERelicType.HalfHealthAmulet))
		{
			if (PhaseCounter > 0 && PhaseCounter % 2 == 0)
			{
				bool isHalfHealthOrBelow = JoeyGameControl.Instance.IsPlayerHalfHealth();
				if (isHalfHealthOrBelow)
				{
					// 血量小于等于50%，回复1HP
					ApplyPlayerHealthChange(1, true);
				}
				else
				{
					// 血量大于50%，扣除1HP
					ApplyPlayerHealthChange(-1, false);
				}
			}
		}
	}

	/// <summary>
	/// 处理技能施放事件（用于魔法杖等视作施放技能的效果）
	/// </summary>
	void OnSkillCast(object[] paraArray)
	{
		TryArcaneOrbTrigger();
	}

	/// <summary>
	/// 奥术宝珠效果：每施放三次技能获得一张技能牌4013
	/// </summary>
	private void TryArcaneOrbTrigger()
	{
		if (DataSystem.Instance.HasRelic(ERelicType.ArcaneOrb))
		{
			m_ArcaneOrbSkillCounter++;
			if (m_ArcaneOrbSkillCounter >= 5)
			{
				m_ArcaneOrbSkillCounter = 0;
				AddCardToBag("4013");
				Debug.Log("ArcaneOrb triggered: Added card 4013 to bag");
			}
		}
	}

	/// <summary>
	/// 魔剑士指环效果：加入手牌的武器牌变成魔力剑(1021)，防御牌变成魔力盾(2014)
	/// </summary>
	/// <param name="cardControl">要转换的卡牌控制器</param>
	/// <returns>转换后的卡牌类型</returns>
	private ECardType TryApplyMagicSwordsmanRing(UICardSimpleControl cardControl)
	{
		if (!DataSystem.Instance.HasRelic(ERelicType.MagicSwordsmanRing))
		{
			return cardControl.CardType;
		}

		Card card = cardControl.CardData;
		ECardType cardType = cardControl.CardType;

		// 武器牌变成魔力剑(1021)
		if (cardType == ECardType.attack && card.id != "1021" && card.id != "1011" && card.id != "1019")
		{
			Card magicSwordTemplate = GData.Instance.GetCardConfigById("1021");
			if (magicSwordTemplate != null)
			{
				card.cardImage = magicSwordTemplate.cardImage;
				card.cardBackground = magicSwordTemplate.cardBackground;
				card.cardName = magicSwordTemplate.cardName;
				card.description = magicSwordTemplate.description;
				card.id = magicSwordTemplate.id;
				card.SetAttack(magicSwordTemplate.currentAttack);
				card.effectId = magicSwordTemplate.effectId;
				cardControl.SetData(card);
				Debug.Log($"MagicSwordsmanRing: Converted attack card to Magic Sword (1021)");
			}
		}
		// 防御牌变成魔力盾(2014)
		else if (cardType == ECardType.defence && card.id != "2014")
		{
			Card magicShieldTemplate = GData.Instance.GetCardConfigById("2014");
			if (magicShieldTemplate != null)
			{
				card.cardImage = magicShieldTemplate.cardImage;
				card.cardBackground = magicShieldTemplate.cardBackground;
				card.cardName = magicShieldTemplate.cardName;
				card.description = magicShieldTemplate.description;
				card.id = magicShieldTemplate.id;
				card.currentDefence = magicShieldTemplate.currentDefence;
				card.effectId = magicShieldTemplate.effectId;
				cardControl.SetData(card);
				Debug.Log($"MagicSwordsmanRing: Converted defence card to Magic Shield (2014)");
			}
		}

		return cardType;
	}

}